#!/usr/bin/env python3
"""Append original, syllabus-aligned FAA MCQs. Skips any stem already in the bank.

Questions are written from the official Advt. 10 of 2025 topics (JKSSB syllabus),
not copied from commercial PDF compilations in fianance/.
"""

from __future__ import annotations

import json
import random
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from build_faa_bank import OUT, item, pack_options  # noqa: E402

SEED = 2026
ROOT = Path(__file__).resolve().parents[1]


def load_bank(name: str) -> dict:
    return json.loads((OUT / f"{name}.json").read_text(encoding="utf-8"))


def save_bank(name: str, bank: dict) -> None:
    bank["question_count"] = len(bank["questions"])
    (OUT / f"{name}.json").write_text(json.dumps(bank, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")


def append(name: str, prefix: str, subject: str, rows: list[tuple], rng: random.Random) -> int:
    bank = load_bank(name)
    seen = {q["question"] for q in bank["questions"]}
    n0 = len(bank["questions"])
    i = n0
    added = 0
    for topic, q, c, wrong, expl in rows:
        if q in seen:
            continue
        seen.add(q)
        i += 1
        opts, key = pack_options(c, wrong, rng)
        bank["questions"].append(item(f"{prefix}-{i:03d}", subject, topic, q, opts, key, expl, i - 1))
        added += 1
    save_bank(name, bank)
    print(f"{name}: {n0} → {len(bank['questions'])} (+{added})")
    return added


