def main() -> None:
    rng = random.Random(SEED)
    total = 0
    total += append("gk-jk", "faa-gk", "General Knowledge with special reference to J&K UT", gk_extra(), rng)
    total += append("accountancy", "faa-accountancy", "Accountancy and Book Keeping", acc_extra(), rng)
    total += append("economics", "faa-economics", "General Economics", eco_extra(), rng)
    total += append("computers", "faa-computers", "Knowledge of Computers", extra_computers(), rng)
    total += append("english", "faa-english", "General English", extra_english(), rng)
    total += append("science", "faa-science", "General Science", extra_science(), rng)
    total += append("statistics", "faa-statistics", "Statistics", extra_stats(), rng)
    total += append("mathematics", "faa-mathematics", "Mathematics", extra_math(), rng)

    latest = len(json.loads((OUT / "latest-pattern.json").read_text())["questions"])
    grand = 0
    for p in OUT.glob("*.json"):
        bank = json.loads(p.read_text())
        grand += len(bank.get("questions") or [])
    manifest_path = ROOT / "data" / "qbanks" / "finance" / "accounts-assistant-finance.json"
    manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    manifest["question_count"] = grand
    manifest_path.write_text(json.dumps(manifest, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    catalog_path = ROOT / "data" / "catalog.json"
    catalog = json.loads(catalog_path.read_text(encoding="utf-8"))
    catalog["categories"][0]["posts"][0]["question_count"] = grand
    catalog_path.write_text(json.dumps(catalog, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    index_path = ROOT / "data" / "index.json"
    index = json.loads(index_path.read_text(encoding="utf-8"))
    index["datasets"][0]["question_count"] = grand
    index_path.write_text(json.dumps(index, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    print(f"Added {total} new stems. Grand total {grand} (includes {latest} latest-pattern).")


if __name__ == "__main__":
    main()
